const event = $json.headers?.['x-github-event'];
const payload = $json.body || {};
const repo = payload.repository?.full_name;

if (repo !== 'docrod29-ai/agenda-medica') return [];

const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};

const now = Date.now();
for (const [key, value] of Object.entries(state.seen)) {
  if (typeof value !== 'number' || now - value > 7 * 24 * 60 * 60 * 1000) delete state.seen[key];
}

function once(key) {
  if (state.seen[key]) return false;
  state.seen[key] = now;
  return true;
}

function output(prNumber, sha, command, reason) {
  if (!Number.isInteger(prNumber) || !/^[0-9a-f]{40}$/.test(sha || '') || !command) return [];
  const key = `${command.split(' ')[0]}:${prNumber}:${sha}`;
  if (!once(key)) return [];
  return [{ json: { prNumber, sha, command, reason } }];
}

if (event === 'workflow_run' && payload.action === 'completed') {
  const run = payload.workflow_run || {};
  const prNumber = Array.isArray(run.pull_requests) ? run.pull_requests[0]?.number : undefined;
  if (
    run.name === 'CI' &&
    run.conclusion === 'success' &&
    typeof run.head_branch === 'string' &&
    run.head_branch.startsWith('product/') &&
    prNumber &&
    /^[0-9a-f]{40}$/.test(run.head_sha || '')
  ) {
    return output(
      prNumber,
      run.head_sha,
      `/ausculta-codex-judge ${run.head_sha}`,
      'canonical_ci_green'
    );
  }
  return [];
}

if (event === 'issue_comment' && payload.action === 'created' && payload.issue?.pull_request) {
  const comment = payload.comment || {};
  if (comment.user?.login !== 'github-actions[bot]') return [];

  const body = String(comment.body || '');
  const fenced = body.match(/```(?:json)?\s*(\{[\s\S]*?"verdict"[\s\S]*?\})\s*```/i);
  const loose = body.match(/(\{[\s\S]*"verdict"\s*:\s*"(?:PASS|FAIL)"[\s\S]*\})/i);
  const raw = fenced?.[1] || loose?.[1];
  if (!raw) return [];

  let verdict;
  try { verdict = JSON.parse(raw); } catch { return []; }

  const sha = verdict.audited_sha;
  if (
    !/^[0-9a-f]{40}$/.test(sha || '') ||
    verdict.independent !== true ||
    verdict.read_only !== true
  ) return [];

  const blockers = Array.isArray(verdict.findings)
    ? verdict.findings.filter((f) => f?.blocking === true && ['P0', 'P1'].includes(f?.severity))
    : [];

  if (verdict.verdict === 'FAIL' && blockers.length > 0) {
    return output(
      payload.issue.number,
      sha,
      `/ausculta-claude-writer ${sha}`,
      `blocking_findings_${blockers.length}`
    );
  }
}

return [];
